/* МОРСКОЙ БОЙ против компьютера на клетках листа.
   Слева ваш флот, справа поле противника. Щелчок по клетке противника — выстрел:
   попали — стреляете ещё, промахнулись — стреляет компьютер. Корабли (4, 3, 3, 2, 2, 2, 1, 1, 1, 1)
   не касаются друг друга даже углами; вокруг потопленного корабля клетки отмечаются сами.
   Компьютер на «обычном» уровне бьёт по шахматке и добивает раненых, на «сильном» —
   считает, где корабль вероятнее всего (по всем возможным расстановкам оставшихся). */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

const Р0 = 2, С0 = 1, N = 10, СТОЯНКА = {r: 1, c: 0};
const МОИ_С = С0 + 1, ЕГО_С = С0 + 13;          /* первые столбцы полей: C и O */
const БУКВЫ = 'АБВГДЕЖЗИК';
const ФЛОТ = [4, 3, 3, 2, 2, 2, 1, 1, 1, 1];
const ПАМЯТЬ = 'морской-бой';
const МОРЕ = ['#eef3fd', '#e2eafa'], ТУМАН = ['#d6e2fa', '#cad9f6'];

let игра = null;  /* {лист, уровень, мои: [[i…]], его: [[i…]], поМне: [100] (0 — не стрелял, 1 — мимо, 2 — попал), поНему: [100], ранен: [], ход: 'я'|'он', конец, выстрелов} */

const ряд = i => Math.floor(i / N), стлб = i => i % N;
const имяКлетки = i => БУКВЫ[стлб(i)] + (ряд(i) + 1);
function соседи8(i){ const out = []; for(let dr = -1; dr <= 1; dr++) for(let dc = -1; dc <= 1; dc++){ if(!dr && !dc) continue; const r = ряд(i) + dr, c = стлб(i) + dc; if(r >= 0 && c >= 0 && r < N && c < N) out.push(r * N + c); } return out; }
function соседи4(i){ return [[-1, 0], [1, 0], [0, -1], [0, 1]].map(([dr, dc]) => [ряд(i) + dr, стлб(i) + dc]).filter(([r, c]) => r >= 0 && c >= 0 && r < N && c < N).map(([r, c]) => r * N + c); }

/* --- расстановка: случайно, корабли не касаются даже углами --- */
function расставить(){
  for(let попытка = 0; попытка < 500; попытка++){
    const занято = new Array(N * N).fill(0), корабли = [];
    let ок = true;
    for(const длина of ФЛОТ){
      const места = [];
      for(let r = 0; r < N; r++) for(let c = 0; c < N; c++) for(const гор of [true, false]){
        const клетки = []; for(let k = 0; k < длина; k++) клетки.push(гор ? [r, c + k] : [r + k, c]);
        if(клетки.some(([rr, cc]) => rr >= N || cc >= N)) continue;
        const и = клетки.map(([rr, cc]) => rr * N + cc);
        if(и.some(j => занято[j])) continue;
        места.push(и);
        if(длина === 1) break;
      }
      if(!места.length){ ок = false; break; }
      const корабль = места[Math.floor(Math.random() * места.length)];
      корабли.push(корабль);
      for(const j of корабль){ занято[j] = 1; for(const s of соседи8(j)) занято[s] = 1; }
    }
    if(ок) return корабли;
  }
  return null;
}
const корабльВ = (флот, i) => флот.find(к => к.includes(i));
const потоплен = (к, выстрелы) => к.every(j => выстрелы[j] === 2);

/* --- рисование --- */
function клеткаЛиста(моё, i){ return клетка(Р0 + 1 + ряд(i), (моё ? МОИ_С : ЕГО_С) + стлб(i)); }
const ОСНОВА = {align: 'center', valign: 'middle', b: 1, size: 12};
function рисоватьМою(i){
  const к = клеткаЛиста(true, i), выстрел = игра.поНему[i], корабль = корабльВ(игра.мои, i), тон = (ряд(i) + стлб(i)) % 2;
  if(корабль){
    const весь = потоплен(корабль, игра.поНему);
    к.значение = выстрел === 2 ? '✕' : '';
    к.стиль = Object.assign({}, ОСНОВА, {fill: выстрел === 2 ? (весь ? '#b42318' : '#e5484d') : '#7d8aa3', color: '#ffffff'});
    return;
  }
  к.значение = выстрел === 1 ? '•' : '';
  к.стиль = Object.assign({}, ОСНОВА, {fill: МОРЕ[тон], color: '#5b6b86', size: 9});
}
function рисоватьЕго(i){
  const к = клеткаЛиста(false, i), выстрел = игра.поМне[i], тон = (ряд(i) + стлб(i)) % 2;
  if(выстрел === 2){
    const весь = потоплен(корабльВ(игра.его, i), игра.поМне);
    к.значение = '✕';
    к.стиль = Object.assign({}, ОСНОВА, {fill: весь ? '#e5484d' : '#f59e9e', color: весь ? '#ffffff' : '#7f1d1d'});
    return;
  }
  if(выстрел === 1){ к.значение = '•'; к.стиль = Object.assign({}, ОСНОВА, {fill: '#f6f8fb', color: '#5b6b86', size: 9}); return; }
  /* после поражения показываем, где стояли уцелевшие корабли */
  const показать = игра.конец === 'поражение' && корабльВ(игра.его, i);
  к.значение = '';
  к.стиль = Object.assign({}, ОСНОВА, {fill: показать ? '#9aa4b5' : ТУМАН[тон]});
}
function рамкиИПодписи(){
  const ЗАГ = {align: 'center', valign: 'middle', b: 1, size: 9, color: '#5b6b86'};
  for(const [нач, имя] of [[МОИ_С, 'Ваш флот'], [ЕГО_С, 'Противник']]){
    const з = клетка(1, нач); з.значение = имя; з.стиль = {b: 1, size: 11, color: '#151c2e'};
    for(let c = 0; c < N; c++){ const к = клетка(Р0, нач + c); к.значение = БУКВЫ[c]; к.стиль = ЗАГ; }
    for(let r = 0; r < N; r++){ const к = клетка(Р0 + 1 + r, нач - 1); к.значение = r + 1; к.стиль = ЗАГ; }
  }
}
const осталось = (флот, выстрелы) => флот.filter(к => !потоплен(к, выстрелы)).length;
function шапка(){
  const к = клетка(0, С0);
  к.значение = 'Морской бой · ' + (игра.конец === 'победа' ? 'ПОБЕДА за ' + число(игра.выстрелов, 'выстрел', 'выстрела', 'выстрелов') : игра.конец === 'поражение' ? 'флот потоплен — победил компьютер'
    : 'у вас ' + число(осталось(игра.мои, игра.поНему), 'корабль', 'корабля', 'кораблей') + ', у противника ' + осталось(игра.его, игра.поМне));
  к.стиль = {b: 1, size: 12, color: игра.конец === 'победа' ? '#15803d' : игра.конец === 'поражение' ? '#b91c1c' : '#151c2e'};
}
function нарисоватьВсё(){ рамкиИПодписи(); for(let i = 0; i < N * N; i++){ рисоватьМою(i); рисоватьЕго(i); } шапка(); }
function показатьСчёт(){
  if(!игра){ панель.список('сейчас', [['Бой', 'не начат — нажмите «Новый бой»']]); return; }
  панель.список('сейчас', [['Ваших кораблей', String(осталось(игра.мои, игра.поНему)) + ' из 10'], ['Кораблей противника', String(осталось(игра.его, игра.поМне)) + ' из 10'],
    ['Ваших выстрелов', String(игра.выстрелов)], ['Компьютер', игра.уровень], ['Итог', игра.конец === 'победа' ? 'победа!' : игра.конец === 'поражение' ? 'поражение' : 'идёт бой']]);
}
function показатьСтатистику(){
  const с = хранилище.взять('счёт', {}) || {};
  панель.список('счёт', ['обычный', 'сильный'].map(у => { const x = с[у] || {}; return ['Компьютер, ' + у, 'побед: ' + (x.победы || 0) + ' · поражений: ' + (x.поражения || 0) + (x.лучший ? ' · лучшая победа за ' + число(x.лучший, 'выстрел', 'выстрела', 'выстрелов') : '')]; }));
}
function сохранить(){ лист(игра.лист).запомнить(ПАМЯТЬ, игра); }

/* --- выстрелы --- */
/* Выстрел по флоту: 'мимо' | 'ранен' | 'убит'. Вокруг потопленного — отметки «мимо» (там кораблей быть не может). */
function выстрел(флот, выстрелы, i, рисовать){
  const к = корабльВ(флот, i);
  if(!к){ выстрелы[i] = 1; рисовать(i); return 'мимо'; }
  выстрелы[i] = 2;
  if(потоплен(к, выстрелы)){
    for(const j of к) for(const s of соседи8(j)) if(!выстрелы[s]){ выстрелы[s] = 1; рисовать(s); }
    for(const j of к) рисовать(j);
    return 'убит';
  }
  рисовать(i);
  return 'ранен';
}
/* --- компьютер --- */
function целиКомпьютера(){
  const в = игра.поНему, ранен = игра.ранен.filter(i => в[i] === 2 && !потоплен(корабльВ(игра.мои, i), в));
  if(ранен.length){
    let out = [];
    if(ранен.length >= 2){
      const гор = ряд(ранен[0]) === ряд(ранен[1]);
      const линия = ранен.slice().sort((a, b) => a - b);
      const края = гор ? [линия[0] - 1, линия[линия.length - 1] + 1].filter(j => j >= 0 && ряд(j) === ряд(линия[0]))
                       : [линия[0] - N, линия[линия.length - 1] + N].filter(j => j >= 0 && j < N * N);
      out = края.filter(j => !в[j]);
    } else out = соседи4(ранен[0]).filter(j => !в[j]);
    if(out.length) return out;
  }
  const свободно = []; for(let i = 0; i < N * N; i++) if(!в[i]) свободно.push(i);
  if(игра.уровень === 'сильный'){
    /* плотность: сколько расстановок оставшихся кораблей проходит через клетку */
    const живые = игра.мои.filter(к => !потоплен(к, в)).map(к => к.length);
    const плотность = new Array(N * N).fill(0);
    for(const длина of живые) for(let r = 0; r < N; r++) for(let c = 0; c < N; c++) for(const гор of (длина > 1 ? [true, false] : [true])){
      const клетки = []; let ок = true;
      for(let k = 0; k < длина; k++){ const rr = гор ? r : r + k, cc = гор ? c + k : c; if(rr >= N || cc >= N || в[rr * N + cc]){ ок = false; break; } клетки.push(rr * N + cc); }
      if(ок) for(const j of клетки) плотность[j]++;
    }
    const макс = Math.max(...свободно.map(i => плотность[i]));
    return свободно.filter(i => плотность[i] === макс);
  }
  const шахматка = свободно.filter(i => (ряд(i) + стлб(i)) % 2 === 0);
  return шахматка.length ? шахматка : свободно;
}
function ходКомпьютера(){
  const сводки = [];
  while(!игра.конец){
    const цели = целиКомпьютера();
    const i = цели[Math.floor(Math.random() * цели.length)];
    const итог = выстрел(игра.мои, игра.поНему, i, рисоватьМою);
    сводки.push(имяКлетки(i) + ' — ' + итог);
    if(итог === 'ранен') игра.ранен.push(i);
    if(итог === 'убит') игра.ранен = [];
    if(осталось(игра.мои, игра.поНему) === 0){ конецБоя('поражение'); break; }
    if(итог === 'мимо') break;
  }
  return сводки;
}
function конецБоя(как){
  игра.конец = как;
  if(как === 'поражение') for(let i = 0; i < N * N; i++) if(!игра.поМне[i]) рисоватьЕго(i);
  const с = хранилище.взять('счёт', {}) || {}, у = игра.уровень;
  с[у] = с[у] || {};
  if(как === 'победа'){ с[у].победы = (с[у].победы || 0) + 1; if(!с[у].лучший || игра.выстрелов < с[у].лучший) с[у].лучший = игра.выстрелов; }
  else с[у].поражения = (с[у].поражения || 0) + 1;
  хранилище.положить('счёт', с); показатьСтатистику();
}

/* --- обработчики --- */
function Старт(){
  показатьСтатистику();
  let м = null;
  try { м = лист().память(ПАМЯТЬ); } catch(e){}
  if(м && м.мои && !м.конец){ игра = м; панель.сообщение('Незаконченный бой на этом листе — продолжаем.'); }
  показатьСчёт();
}
async function НовыйБой(){
  const п = параметры({});
  const имяЛиста = книга.выделение ? книга.выделение.лист : книга.листы[0];
  let своё = null;
  try { своё = лист().память(ПАМЯТЬ); } catch(e){}
  if(!своё && !(await областьПуста(0, С0, Р0 + N, ЕГО_С + N - 1))){
    if(!(await диалог.вопрос('На этом листе в B1:X13 уже что-то есть. Поля лягут поверх. Лучше завести для игры пустой лист (+ внизу). Всё равно положить здесь?'))) return;
  }
  игра = {лист: имяЛиста, уровень: п.уровень || 'обычный', мои: расставить(), его: расставить(),
          поМне: new Array(N * N).fill(0), поНему: new Array(N * N).fill(0), ранен: [], конец: null, выстрелов: 0};
  клеткиКвадратом(Р0, С0, Р0 + N, ЕГО_С + N - 1, 26);
  await обновитьВысоты();
  ширинаСтолбца(МОИ_С + N, 26); ширинаСтолбца(МОИ_С + N + 1, 26);
  нарисоватьВсё(); сохранить(); показатьСчёт();
  наСтоянку(СТОЯНКА.r, СТОЯНКА.c);
  панель.сообщение('Ваш флот расставлен слева (не нравится — «Расставить заново» до первого выстрела). Стреляйте щелчком по полю противника справа.');
}
function РасставитьЗаново(){
  if(!игра || игра.конец || игра.выстрелов || игра.поНему.some(x => x)){ панель.сообщение('Переставить флот можно только до первого выстрела.'); return; }
  игра.мои = расставить();
  for(let i = 0; i < N * N; i++) рисоватьМою(i);
  сохранить(); панель.сообщение('Флот переставлен.');
}
function Ход(){
  const п = книга.повод;
  if(!игра || игра.конец || !п || !п.адрес || п.лист !== игра.лист || п.клеток > 1) return;
  const r = п.строка - 1 - (Р0 + 1), c = п.столбец - 1 - ЕГО_С;
  if(r < 0 || c < 0 || r >= N || c >= N) return;
  наСтоянку(СТОЯНКА.r, СТОЯНКА.c);
  const i = r * N + c;
  if(игра.поМне[i]){ панель.сообщение('Сюда уже стреляли.'); return; }
  игра.выстрелов++;
  const итог = выстрел(игра.его, игра.поМне, i, рисоватьЕго);
  let слово = 'Ваш выстрел ' + имяКлетки(i) + ': ' + итог + '.';
  if(осталось(игра.его, игра.поМне) === 0){ конецБоя('победа'); слово = 'Победа! Флот противника потоплен за ' + число(игра.выстрелов, 'выстрел', 'выстрела', 'выстрелов') + '.'; }
  else if(итог === 'мимо'){
    const ответ = ходКомпьютера();
    слово += ' Компьютер: ' + ответ.join(', ') + '.';
    if(игра.конец === 'поражение') слово += ' Ваш флот потоплен. Уцелевшие корабли противника показаны серым.';
  } else слово += ' Стреляйте ещё.';
  шапка(); сохранить(); показатьСчёт();
  панель.сообщение(слово);
}
function Правка(){
  const п = книга.повод;
  if(!игра || п.строение || п.откуда === 'плагин') return;
  const наПоле = (п.клетки || []).some(к => к.лист === игра.лист && к.строка - 1 <= Р0 + N && к.столбец - 1 >= С0 && к.столбец - 1 < ЕГО_С + N);
  if(!наПоле) return;
  нарисоватьВсё();
  панель.сообщение('Поля правятся только выстрелами — восстановил их.');
}
